package net.minecraft.world.item;public class ItemStack {public static final ItemStack EMPTY=new ItemStack();public long money;private Item item;private int count;private String nbt="";public ItemStack(){}public ItemStack(Item item,int count){this.item=item;this.count=count;}public boolean isEmpty(){return this==EMPTY || ((item==null || count<=0) && money<=0);}public Item getItem(){return item;}public boolean is(Item x){return item==x;}public int getCount(){return count;}public void setCount(int n){count=n;}public int getMaxStackSize(){return 64;}public net.minecraft.nbt.CompoundTag save(net.minecraft.nbt.CompoundTag tag){tag.putInt("Count",count);tag.putString("Item",item==null?"":item.toString());return tag;}public ItemStack copy(){ItemStack s=new ItemStack(item,count);s.nbt=nbt;s.money=money;return s;}public void grow(int n){count+=n;}public void shrink(int n){count-=n;}public static boolean isSameItemSameTags(ItemStack a,ItemStack b){return a.item==b.item && a.nbt.equals(b.nbt);}}